using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Pipes;
using System.Linq;
using System.Security.Cryptography;
using System.Security.Principal;
using System.Text;
using System.Threading;
using System.Web.Script.Serialization;

// Standalone local benchmark. It creates only disposable fixtures beneath the
// caller-selected evidence directory; it never starts the desktop UI.
class PerformanceBenchmark {
    static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
    static readonly uint[] ReferenceTable=MakeReferenceTable();
    static readonly List<Dictionary<string,object>> Results=new List<Dictionary<string,object>>();
    static readonly Dictionary<string,object> Metadata=new Dictionary<string,object>();
    static string root;
    static byte[] smallData;
    sealed class AppClient : IDisposable {
        public readonly string Name,Exe,Profile,Pipe;
        Process service;
        public AppClient(string name,string exe){Name=name;Exe=Path.GetFullPath(exe);Profile=Path.Combine(root,"profiles",name);Directory.CreateDirectory(Profile);using(var sha=SHA256.Create()){string id=BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(Profile.ToUpperInvariant()))).Replace("-","").Substring(0,12);Pipe="Evacopy.Service.v2."+WindowsIdentity.GetCurrent().User.Value.Replace('-','_')+"."+id;}
            var start=new ProcessStartInfo(Exe,"--service"){UseShellExecute=false,CreateNoWindow=true};start.EnvironmentVariables["EVACOPY_PROFILE"]=Profile;service=Process.Start(start);
            var deadline=DateTime.UtcNow.AddSeconds(30);while(true){try{Send(new Dictionary<string,object>{{"Command","ping"}});break;}catch(IOException){}catch(TimeoutException){}if(DateTime.UtcNow>deadline)throw new Exception("Service startup timed out: "+name);Thread.Sleep(50);}
        }
        public Dictionary<string,object> Send(object request){using(var pipe=new NamedPipeClientStream(".",Pipe,PipeDirection.InOut,PipeOptions.Asynchronous)){pipe.Connect(1000);using(var writer=new StreamWriter(pipe,new UTF8Encoding(false),4096,true){AutoFlush=true})using(var reader=new StreamReader(pipe,Encoding.UTF8,true,4096,true)){writer.WriteLine(Json.Serialize(request));var read=reader.ReadLineAsync();if(!read.Wait(20000))throw new TimeoutException("Service response timeout");var reply=Json.Deserialize<Dictionary<string,object>>(read.Result);object error;if(reply.TryGetValue("Error",out error)&&error!=null)throw new Exception(Name+": "+error);return reply;}}}
        public Dictionary<string,object> Run(string source,string destination,string operation,bool include){var job=new Dictionary<string,object>{{"Sources",new[]{source}},{"Destination",destination},{"Operation",operation},{"DeleteSource",operation=="Move"},{"VerifyCrc",false},{"IncludeSourceFolder",include},{"Threads",32},{"Priority","Normal"},{"CopyMode","Standard"}};
            var watch=Stopwatch.StartNew();var reply=Send(new Dictionary<string,object>{{"Command","submit"},{"Job",job}});string id=(string)reply["Id"];string statePath=Path.Combine(Profile,id+".state");Dictionary<string,object> state=null;var deadline=DateTime.UtcNow.AddMinutes(5);
            while(DateTime.UtcNow<deadline){try{using(var file=new FileStream(statePath,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(file))state=Json.Deserialize<Dictionary<string,object>>(reader.ReadToEnd());if(Convert.ToBoolean(state["Finished"]))break;}catch(IOException){}Thread.Sleep(10);}
            watch.Stop();if(state==null||!Convert.ToBoolean(state["Finished"])||!Convert.ToBoolean(state["Successful"]))throw new Exception(Name+" job failed: "+Json.Serialize(state));state["ElapsedMilliseconds"]=watch.Elapsed.TotalMilliseconds;state["JobId"]=id;return state;
        }
        public void Dispose(){try{Send(new Dictionary<string,object>{{"Command","exit"}});}catch{}if(service!=null){if(!service.WaitForExit(20000))throw new Exception("Benchmark service did not exit: "+Name);service.Dispose();}}
    }
    static uint[] MakeReferenceTable(){var result=new uint[256];for(uint i=0;i<256;i++){uint value=i;for(int bit=0;bit<8;bit++)value=(value&1)!=0?(value>>1)^0xedb88320U:value>>1;result[i]=value;}return result;}
    static uint Reference(byte[] bytes){uint crc=0xffffffff;for(int i=0;i<bytes.Length;i++)crc=ReferenceTable[(crc^bytes[i])&255]^(crc>>8);return crc^0xffffffff;}
    static uint Accelerated(byte[] bytes){return FastCrc32.Update(0xffffffff,bytes,0,bytes.Length)^0xffffffff;}
    static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
    static string Quote(string value){return "\""+value+"\"";}
    static string Hash(string path){using(var sha=SHA256.Create())using(var stream=File.OpenRead(path))return BitConverter.ToString(sha.ComputeHash(stream));}
    static void Add(string fixture,string engine,int run,double milliseconds,Dictionary<string,object> state){object probes=null,method=null,crc=null;if(state!=null){state.TryGetValue("ProgressMetadataProbes",out probes);state.TryGetValue("TransferMethod",out method);state.TryGetValue("CrcBytesRead",out crc);}Results.Add(new Dictionary<string,object>{{"Fixture",fixture},{"Engine",engine},{"Run",run},{"ElapsedMilliseconds",milliseconds},{"ProgressMetadataProbes",probes},{"TransferMethod",method},{"CrcBytesRead",crc}});Console.WriteLine(fixture+" / "+engine+" / run "+run+": "+milliseconds.ToString("N1")+" ms; probes="+(probes??"not reported")+"; method="+(method??"not reported"));WriteResults();}
    static void WriteResults(){File.WriteAllText(Path.Combine(root,"results.json"),Json.Serialize(new Dictionary<string,object>{{"Metadata",Metadata},{"Caveats","Single machine; warm-cache observations; no system cache clearing; fixture generation and content verification excluded; app timings include submit, worker startup, scanning, copying/moving, checking, completion polling; brokers warmed before timing."},{"Results",Results}}));}
    static void VerifySmall(string destination,int count){var files=Directory.GetFiles(destination,"*",SearchOption.AllDirectories);Assert(files.Length==count,"Small-file count mismatch");foreach(var file in files)Assert(File.ReadAllBytes(file).SequenceEqual(smallData),"Small-file content mismatch: "+file);}
    static void SmallFiles(AppClient baseline,AppClient candidate,int count){string source=Path.Combine(root,"fixtures","small source");Directory.CreateDirectory(source);smallData=new byte[4096];new Random(919).NextBytes(smallData);for(int i=0;i<count;i++){string dir=Path.Combine(source,"group "+(i/100).ToString("D3"));Directory.CreateDirectory(dir);File.WriteAllBytes(Path.Combine(dir,"file "+i.ToString("D6")+".bin"),smallData);}
        // Warm JIT/process paths with a separate tiny fixture before measured jobs.
        string warm=Path.Combine(root,"fixtures","warm source");Directory.CreateDirectory(warm);File.WriteAllText(Path.Combine(warm,"warm.txt"),"warm");baseline.Run(warm,Path.Combine(root,"warm baseline"),"Copy",false);candidate.Run(warm,Path.Combine(root,"warm candidate"),"Copy",false);
        for(int run=1;run<=3;run++){string[] order=run%2==1?new[]{"baseline","candidate","robocopy"}:new[]{"robocopy","candidate","baseline"};foreach(string engine in order){string destination=Path.Combine(root,"small targets",engine+" "+run);double elapsed;Dictionary<string,object> state=null;if(engine=="robocopy"){var info=new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.System),"robocopy.exe"),Quote(source)+" "+Quote(destination)+" /E /MT:32 /R:1 /W:1 /XJ /COPY:DAT /DCOPY:DAT /BYTES /NP /UNILOG:"+Quote(Path.Combine(root,"direct-small-"+run+".log"))){UseShellExecute=false,CreateNoWindow=true};var watch=Stopwatch.StartNew();using(var process=Process.Start(info)){process.PriorityClass=ProcessPriorityClass.Normal;process.WaitForExit();Assert(process.ExitCode<8,"Direct Robocopy failed");}watch.Stop();elapsed=watch.Elapsed.TotalMilliseconds;}else{var client=engine=="baseline"?baseline:candidate;state=client.Run(source,destination,"Copy",false);elapsed=Convert.ToDouble(state["ElapsedMilliseconds"]);Assert(Convert.ToInt64(state["CrcBytesRead"])==0,"Unexpected CRC data reads");}VerifySmall(destination,count);Add("small-files-"+count,engine,run,elapsed,state);}}
    }
    static void Moves(AppClient baseline,AppClient candidate){string original=Path.Combine(root,"fixtures","move payload.bin");Directory.CreateDirectory(Path.GetDirectoryName(original));var block=new byte[1024*1024];new Random(420).NextBytes(block);using(var file=File.Create(original))for(int i=0;i<128;i++)file.Write(block,0,block.Length);string expected=Hash(original);
        for(int run=1;run<=3;run++)foreach(var client in run%2==1?new[]{baseline,candidate}:new[]{candidate,baseline}){string source=Path.Combine(root,"move fixtures",client.Name+" "+run,"source folder");Directory.CreateDirectory(source);File.Copy(original,Path.Combine(source,"payload.bin"));string destination=Path.Combine(root,"move targets",client.Name+" "+run);var state=client.Run(source,destination,"Move",true);string target=Path.Combine(destination,"source folder","payload.bin");Assert(!Directory.Exists(source),"Move left source folder");Assert(File.Exists(target)&&new FileInfo(target).Length==128L*1024*1024&&Hash(target)==expected,"Move content mismatch");Assert(Convert.ToInt64(state["CrcBytesRead"])==0,"Move unexpectedly read CRC");Add("same-volume-move-128MiB",client.Name,run,Convert.ToDouble(state["ElapsedMilliseconds"]),state);}
    }
    static void Crc(){var data=new byte[32*1024*1024];new Random(1234).NextBytes(data);Assert(Reference(data)==Accelerated(data),"CRC mismatch");Reference(data);Accelerated(data);
        for(int run=1;run<=3;run++)foreach(string engine in run%2==1?new[]{"bytewise","slicing-by-8"}:new[]{"slicing-by-8","bytewise"}){uint checksum=0;var watch=Stopwatch.StartNew();for(int i=0;i<8;i++)checksum=engine=="bytewise"?Reference(data):Accelerated(data);watch.Stop();Assert(checksum==Reference(data),"CRC timing result mismatch");Add("crc-32MiB-x8",engine,run,watch.Elapsed.TotalMilliseconds,null);}
    }
    static void Summary(){var output=new StringBuilder();output.AppendLine("# Local performance observations");output.AppendLine();output.AppendLine("Single-machine, warm-cache observations with three runs per engine. No cache clearing; fixture generation and independent byte/hash verification are outside timed regions. Services are warmed. These results are not general speed guarantees. Missing baseline metadata telemetry is recorded as null, not zero.");output.AppendLine();output.AppendLine("| Fixture | Engine | Median ms |");output.AppendLine("| --- | --- | ---: |");foreach(var group in Results.GroupBy(r=>r["Fixture"].ToString()+"|"+r["Engine"].ToString())){var sorted=group.Select(r=>Convert.ToDouble(r["ElapsedMilliseconds"])).OrderBy(v=>v).ToArray();var first=group.First();output.AppendLine("| "+first["Fixture"]+" | "+first["Engine"]+" | "+sorted[sorted.Length/2].ToString("N2")+" |");}File.WriteAllText(Path.Combine(root,"summary.md"),output.ToString());Console.WriteLine(output.ToString());}
    static int Main(string[] args){if(args.Length<3){Console.Error.WriteLine("Usage: PerformanceBenchmark baseline.exe candidate.exe evidence-directory [small-file-count]");return 2;}root=Path.GetFullPath(args[2]);Directory.CreateDirectory(root);try{int count=args.Length>3?Int32.Parse(args[3]):6000;Metadata["StartedUtc"]=DateTime.UtcNow.ToString("o");Metadata["BaselineExe"]=Path.GetFullPath(args[0]);Metadata["CandidateExe"]=Path.GetFullPath(args[1]);Metadata["BaselineSha256"]=Hash(args[0]).Replace("-","").ToLowerInvariant();Metadata["CandidateSha256"]=Hash(args[1]).Replace("-","").ToLowerInvariant();Metadata["OS"]=Environment.OSVersion.ToString();Metadata["ProcessorCount"]=Environment.ProcessorCount;Metadata["Threads"]=32;Metadata["Priority"]="Normal";Metadata["SmallFileCount"]=count;using(var baseline=new AppClient("baseline",args[0]))using(var candidate=new AppClient("candidate",args[1])){SmallFiles(baseline,candidate,count);Moves(baseline,candidate);}Crc();Summary();return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(root,"ERROR.txt"),ex.ToString());Console.Error.WriteLine(ex);return 1;}}
}
